function Tooltip({ text }: { text: string }) {
  const ref = useRef<HTMLDivElement>(null)
  const [h, setH] = useState(0)
  // layout: measure before paint to avoid a flash
  useLayoutEffect(() => {
    const next = ref.current?.getBoundingClientRect().height ?? 0
    if (next !== h) setH(next) // guard — height in deps without this loops
  }, [text, h])
  // render stays pure: no Date.now(), no Math.random()
  return <div ref={ref} style={{ top: h }}>{text}</div>
}

