class WidgetBoundary extends Component<{ children: React.ReactNode }, { err: Error | null }> {
  state = { err: null as Error | null }
  static getDerivedStateFromError(err: Error) {
    return { err } // render fallback
  }
  componentDidCatch(err: Error, info: React.ErrorInfo) {
    report(err, info) // Sentry — does not catch onClick or fetch
  }
  render() {
    return this.state.err ? <Failed onRetry={() => this.setState({ err: null })} /> : this.props.children
  }
}

